147:     private JornadaResponse montarJornada(Profissional profissional) {
148:         List<JornadaIntervaloResponse> intervalos = jornadas
149:                 .findByProfissionalIdOrderByDiaSemanaAscHoraInicioAsc(profissional.getId()).stream()
150:                 .map(JornadaIntervaloResponse::from)
151:                 .toList();
152:         return new JornadaResponse(profissional.getId(), profissional.getUnidade().getId(), intervalos);
153:     }
154: 
155:     private JornadaResponse salvarJornada(Profissional profissional, JornadaRequest request,
156:                                          String origem) {
157:         List<JornadaIntervaloRequest> pedidos = request.intervalosSeguros();
158:         validarIntervalos(pedidos);
159: 
160:         Map<Integer, List<JanelaTrabalho>> porDia = agruparPorDia(pedidos);
161:         LocalDateTime agora = agora(profissional.getUnidade());
162:         List<ItemConflito> conflitos = new ArrayList<>();
163:         for (Atendimento atendimento : atendimentos
164:                 .findByProfissionalIdAndInicioGreaterThanEqualOrderByInicioAsc(profissional.getId(), agora)) {
165:             if (atendimento.getStatus() == AtendimentoStatus.CANCELADO) {
166:                 continue;
167:             }
168:             LocalDate data = atendimento.getInicio().toLocalDate();
169:             if (excecoes.findByProfissionalIdAndData(profissional.getId(), data).isPresent()) {
170:                 continue;
171:             }
172:             List<JanelaTrabalho> janelasDoDia =
173:                     porDia.getOrDefault(atendimento.getInicio().getDayOfWeek().getValue(), List.of());
174:             if (!cabe(atendimento, janelasDoDia)) {
175:                 conflitos.add(ItemConflito.from(atendimento));
176:             }
177:         }
178:         recusarSeHouverConflito(conflitos, "a nova jornada deixaria atendimentos futuros fora das janelas");
179: 
180:         jornadas.deleteByProfissionalId(profissional.getId());
181:         jornadas.flush();
182:         pedidos.forEach(pedido -> jornadas.save(new JornadaIntervalo(
183:                 profissional, pedido.diaSemana(), pedido.horaInicio(), pedido.horaFim())));
184:         auditar("JORNADA_ALTERADA", origem, "profissional=" + profissional.getId());
185:         return montarJornada(profissional);
186:     }
187: 
188:     private Map<Integer, List<JanelaTrabalho>> agruparPorDia(List<JornadaIntervaloRequest> pedidos) {
189:         Map<Integer, List<JanelaTrabalho>> porDia = new LinkedHashMap<>();
190:         pedidos.forEach(pedido -> porDia
191:                 .computeIfAbsent(pedido.diaSemana(), chave -> new ArrayList<>())
192:                 .add(new JanelaTrabalho(pedido.horaInicio(), pedido.horaFim())));
193:         return porDia;
194:     }
195: 
196:     private void validarIntervalos(List<JornadaIntervaloRequest> intervaloRequests) {
197:         Map<Integer, List<JornadaIntervaloRequest>> porDia = new LinkedHashMap<>();
198:         intervaloRequests.forEach(intervalo -> porDia
199:                 .computeIfAbsent(intervalo.diaSemana(), chave -> new ArrayList<>())
200:                 .add(intervalo));
201: 
202:         porDia.forEach((dia, doDia) -> {
203:             if (doDia.size() > MAX_INTERVALOS_DIA) {
204:                 throw new IllegalArgumentException("um dia pode ter no maximo " + MAX_INTERVALOS_DIA + " intervalos");
205:             }
206:             List<JornadaIntervaloRequest> ordenados = new ArrayList<>(doDia);
207:             ordenados.sort((a, b) -> a.horaInicio().compareTo(b.horaInicio()));
208:             for (int i = 0; i < ordenados.size(); i++) {
209:                 JornadaIntervaloRequest atual = ordenados.get(i);
210:                 if (!atual.horaInicio().isBefore(atual.horaFim())) {
211:                     throw new IllegalArgumentException("horaInicio deve ser anterior a horaFim");
212:                 }
213:                 if (i > 0 && ordenados.get(i - 1).horaFim().isAfter(atual.horaInicio())) {
214:                     throw new ConflitoException("intervalos da jornada nao podem se sobrepor");
215:                 }
216:             }
217:         });
218:     }
