277:     private ExcecaoResponse salvarExcecao(Profissional profissional, ExcecaoRequest request,
278:                                           Long id, String origem) {
279:         validarHorarios(request.intervalosSeguros(), request.tipo());
280:         boolean duplicada = id == null
281:                 ? excecoes.existsByProfissionalIdAndData(profissional.getId(), request.data())
282:                 : excecoes.existsByProfissionalIdAndDataAndIdNot(profissional.getId(), request.data(), id);
283:         if (duplicada) {
284:             throw new ConflitoException("ja existe uma excecao de jornada para esta data");
285:         }
286: 
287:         ExcecaoJornada excecao = id == null
288:                 ? new ExcecaoJornada(profissional, request.data(), request.tipo())
289:                 : buscarExcecao(profissional, id);
290:         excecao.setData(request.data());
291:         excecao.setTipo(request.tipo());
292:         excecao.setMotivo(opcional(request.motivo()));
293:         if (request.tipo() == TipoExcecaoJornada.FOLGA) {
294:             excecao.substituirIntervalos(List.of());
295:         } else {
296:             excecao.substituirIntervalos(request.intervalosSeguros().stream()
297:                     .map(h -> new ExcecaoJornadaIntervalo(h.horaInicio(), h.horaFim()))
298:                     .toList());
299:         }
300: 
301:         List<JanelaTrabalho> janelas = request.tipo() == TipoExcecaoJornada.JORNADA_ESPECIAL
302:                 ? request.intervalosSeguros().stream()
303:                     .map(h -> new JanelaTrabalho(h.horaInicio(), h.horaFim())).toList()
304:                 : List.of();
305:         List<ItemConflito> conflitos = conflitosDoDia(profissional, request.data(), janelas).stream()
306:                 .map(ItemConflito::from).toList();
307:         recusarSeHouverConflito(conflitos,
308:                 "a excecao deixaria atendimentos futuros fora das janelas");
309: 
310:         ExcecaoJornada salva = excecoes.save(excecao);
311:         auditar("EXCECAO_JORNADA_SALVA", origem, "profissional=" + profissional.getId());
312:         return ExcecaoResponse.from(salva);
313:     }
