381:     private AfastamentoResponse salvarAfastamento(Profissional profissional, AfastamentoRequest request,
382:                                                   Long id, String origem) {
383:         if (request.dataInicio().isAfter(request.dataFim())) {
384:             throw new IllegalArgumentException("dataInicio deve ser anterior ou igual a dataFim");
385:         }
386:         boolean sobreposto = afastamentos
387:                 .findByProfissionalIdAndDataFimGreaterThanEqualAndDataInicioLessThanEqualOrderByDataInicioAsc(
388:                         profissional.getId(), request.dataInicio(), request.dataFim()).stream()
389:                 .anyMatch(afastamento -> id == null || !afastamento.getId().equals(id));
390:         if (sobreposto) {
391:             throw new ConflitoException("ja existe um afastamento neste periodo");
392:         }
393: 
394:         List<ItemConflito> conflitos = conflitosNoPeriodo(
395:                 profissional, request.dataInicio(), request.dataFim()).stream()
396:                 .map(ItemConflito::from).toList();
397:         recusarSeHouverConflito(conflitos,
398:                 "o afastamento deixaria atendimentos futuros fora das janelas");
399: 
400:         Afastamento afastamento = id == null
401:                 ? new Afastamento(profissional, request.dataInicio(), request.dataFim(), request.tipo())
402:                 : buscarAfastamento(profissional, id);
403:         afastamento.setDataInicio(request.dataInicio());
404:         afastamento.setDataFim(request.dataFim());
405:         afastamento.setTipo(request.tipo());
406:         afastamento.setDescricao(opcional(request.descricao()));
407: 
408:         Afastamento salvo = afastamentos.save(afastamento);
409:         auditar("AFASTAMENTO_SALVO", origem, "profissional=" + profissional.getId());
410:         return AfastamentoResponse.from(salvo);
411:     }
