449:     private FeriadoResponse salvarFeriado(Unidade unidade, FeriadoRequest request, Long id,
450:                                           String origem) {
451:         boolean duplicado = id == null
452:                 ? feriados.existsByUnidadeIdAndData(unidade.getId(), request.data())
453:                 : feriados.existsByUnidadeIdAndDataAndIdNot(unidade.getId(), request.data(), id);
454:         if (duplicado) {
455:             throw new ConflitoException("ja existe um feriado nesta data");
456:         }
457: 
458:         List<ItemConflito> conflitos = atendimentosFuturosDaUnidade(unidade, request.data()).stream()
459:                 .map(ItemConflito::from).toList();
460:         recusarSeHouverConflito(conflitos,
461:                 "o feriado deixaria atendimentos futuros fora das janelas");
462: 
463:         Feriado feriado = id == null
464:                 ? new Feriado(unidade, request.data(), request.nome().trim())
465:                 : buscarFeriado(unidade, id);
466:         feriado.setData(request.data());
467:         feriado.setNome(request.nome().trim());
468: 
