711:             throw new IllegalArgumentException("jornada especial exige ao menos um intervalo");
712:         }
713:         List<HorarioRequest> ordenados = new ArrayList<>(horarios);
714:         ordenados.sort((a, b) -> a.horaInicio().compareTo(b.horaInicio()));
715:         for (int i = 0; i < ordenados.size(); i++) {
716:             HorarioRequest atual = ordenados.get(i);
717:             if (!atual.horaInicio().isBefore(atual.horaFim())) {
718:                 throw new IllegalArgumentException("horaInicio deve ser anterior a horaFim");
719:             }
720:             if (i > 0 && ordenados.get(i - 1).horaFim().isAfter(atual.horaInicio())) {
721:                 throw new ConflitoException("intervalos da jornada especial nao podem se sobrepor");
722:             }
723:         }
